"""Lesson storyboards. Each caption identifies the observable outcome of the example."""
SCENES = {}


def scene(day, section, title, caption, drawing, **data):
    SCENES[day] = dict(section=section, title=title, caption=caption, drawing=drawing, **data)


def ledger(day, section, title, caption, fields, *snapshots):
    """The same rows stay in place across snapshots; only changed cells light up."""
    scene(day, section, title, caption, 'ledger', fields=fields, snapshots=snapshots)


def links(day, section, title, caption, headings, left, right, routes):
    """Routes are actual correspondences, including many-to-one and crossed matches."""
    scene(day, section, title, caption, 'links', headings=headings, left=left, right=right, routes=routes)


def relay(day, section, title, caption, *stops):
    """The payload at a stop travels to the next receiver before being transformed."""
    scene(day, section, title, caption, 'relay', stops=stops)


